import { test } from "node:test";
import assert from "node:assert/strict";
import { setImmediate as tick } from "node:timers/promises";
import { CampaignCatalog } from "../src/promos/campaigns.ts";
import { PromoRedeemer } from "../src/promos/redemptions.ts";
import { cancelOrder, placeOrder, type Order } from "../src/promos/checkout.ts";
import type { KeyValueStore } from "../src/promos/kv.ts";

// Redis fake: each command is a network round trip, then runs atomically.
function memoryKv(): KeyValueStore & { data: Map<string, string> } {
    const data = new Map<string, string>();
    return {
        data,
        async get(k) { await tick(); return data.get(k) ?? null; },
        async set(k, v) { await tick(); data.set(k, v); },
        async del(k) { await tick(); data.delete(k); },
        async incrBy(k, d) { await tick(); const n = Number(data.get(k) ?? "0") + d; data.set(k, String(n)); return n; },
        async setIfAbsent(k, v) { await tick(); if (data.has(k)) return false; data.set(k, v); return true; },
    };
}

const now = new Date("2026-11-19T18:00:00Z");

function shop(maxRedemptions = 100) {
    const catalog = new CampaignCatalog();
    catalog.add({ code: "PIZZA20", percentOff: 20, maxDiscountCents: 1000, minOrderCents: 1500, maxRedemptions, expiresAt: new Date("2026-11-30T00:00:00Z") });
    catalog.add({ code: "SUMMER", percentOff: 10, maxDiscountCents: 500, minOrderCents: 0, maxRedemptions: 100, expiresAt: new Date("2026-09-01T00:00:00Z") });
    const kv = memoryKv();
    return { kv, promos: new PromoRedeemer(catalog, kv) };
}

const order = (id: string, customerId: string, subtotalCents = 3000): Order => ({ id, customerId, subtotalCents, deliveryFeeCents: 299, status: "placed" });

test("a valid code discounts the food subtotal, capped, but not the delivery fee", async () => {
    const { promos } = shop();
    const small = await placeOrder(promos, order("o1", "c1", 3000), "pizza20 ", now);
    assert.deepEqual(small.order.promo, { code: "PIZZA20", discountCents: 600 });
    assert.equal(small.totalCents, 3000 - 600 + 299);
    const big = await placeOrder(promos, order("o2", "c2", 9000), "PIZZA20", now);
    assert.equal(big.order.promo?.discountCents, 1000);
});

test("unknown, expired and below-minimum codes are rejected", async () => {
    const { promos } = shop();
    assert.deepEqual(await promos.redeem("NOPE", "c1", "o1", 3000, now), { ok: false, reason: "unknown_code" });
    assert.deepEqual(await promos.redeem("SUMMER", "c1", "o1", 3000, now), { ok: false, reason: "expired" });
    assert.deepEqual(await promos.redeem("PIZZA20", "c1", "o1", 900, now), { ok: false, reason: "below_minimum" });
    assert.equal(await promos.redemptions("PIZZA20"), 0);
});

test("a customer can use a code once, even from two devices at the same moment", async () => {
    const { promos } = shop();
    const [a, b] = await Promise.all([promos.redeem("PIZZA20", "c1", "o1", 3000, now), promos.redeem("PIZZA20", "c1", "o2", 3000, now)]);
    assert.deepEqual([a.ok, b.ok].sort(), [false, true]);
    assert.equal(await promos.redemptions("PIZZA20"), 1);
});

test("a limited code is never redeemed more times than its limit during a rush", async () => {
    const { promos } = shop(10);
    const results = await Promise.all(Array.from({ length: 30 }, (_, i) => promos.redeem("PIZZA20", `c${i}`, `o${i}`, 3000, now)));
    const granted = results.filter((r) => r.ok).length;
    console.log(`granted ${granted} of 10 redemptions; counter says ${await promos.redemptions("PIZZA20")}`);
    assert.equal(granted, 10);
    assert.equal(results.filter((r) => !r.ok && r.reason === "sold_out").length, 20);
});

test("the redemption counter matches the orders that got the discount", async () => {
    const { promos } = shop(50);
    const placed = await Promise.all(Array.from({ length: 12 }, (_, i) => placeOrder(promos, order(`o${i}`, `c${i}`), "PIZZA20", now)));
    assert.equal(placed.filter((p) => p.order.promo).length, 12);
    assert.equal(await promos.redemptions("PIZZA20"), 12);
});

test("cancelling an order gives its redemption to the next customer", async () => {
    const { promos } = shop(1);
    const first = await placeOrder(promos, order("o1", "c1"), "PIZZA20", now);
    assert.deepEqual((await placeOrder(promos, order("o2", "c2"), "PIZZA20", now)).promo, { ok: false, reason: "sold_out" });
    await cancelOrder(promos, first.order);
    await cancelOrder(promos, first.order);
    assert.equal(await promos.redemptions("PIZZA20"), 0);
    const retry = await placeOrder(promos, order("o3", "c2"), "PIZZA20", now);
    assert.equal(retry.promo?.ok, true);
    assert.equal(await promos.redemptions("PIZZA20"), 1);
});

test("releasing someone else's order doesn't free their redemption", async () => {
    const { kv, promos } = shop(5);
    await promos.redeem("PIZZA20", "c1", "o1", 3000, now);
    await promos.release("PIZZA20", "c1", "o-other");
    assert.equal(await promos.redemptions("PIZZA20"), 1);
    assert.equal(kv.data.get("promo:PIZZA20:customer:c1"), "o1");
});
